// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an amount of wei to send as the deposit and an address actor
    function testFuzz_property(uint256 amount, address actor) public {
        // Keep amount within a sensible range (but allow 1..1e30)
        amount = bound(amount, 1, 1e30);
        // Avoid the zero address for actor to be a realistic EOA
        if (actor == address(0)) actor = address(1);

        // Ensure actor has the funds to send
        vm.deal(actor, amount);

        // Record previous depositsCount
        uint256 before = c.depositsCount();

        // Make the call from actor, sending ETH to trigger receive()
        vm.prank(actor);
        // perform low-level call to send ETH so receive() is invoked
        (bool ok, ) = address(c).call{value: amount}("\x00");
        // Even if the call reverts, we proceed to observe the contract state via its getter.
        // The reference contract should always succeed and increment depositsCount by 1.

        uint256 after = c.depositsCount();

        // GENERAL ASSERTION (single assertTrue): the reference C always increases depositsCount by exactly 1
        // For the mutant, there exist inputs (any amount with depositsCount != 0) that will make this false.
        assertTrue(after == before + 1);
    }
}

