pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount within a reasonable nonzero range (still wide)
        vm.assume(amount > 0 && amount <= 1 ether);
        // fund the actor so they can send
        vm.deal(actor, amount);

        // record before
        uint256 before = c.depositsCount();

        // perform the payable call from actor to trigger receive()
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        // call completed (ok true for successful receive; false if reverted)

        // record after
        uint256 afterCount = c.depositsCount();

        // General rule: for any caller and any positive amount, if the payable call succeeded,
        // the reference contract always increments depositsCount by exactly 1.
        // The mutant makes the call succeed but does NOT increment when depositsCount != 0.
        if (ok) {
            assertTrue(afterCount == before + 1);
        } else {
            // If the call reverted, the invariant about increment on success is vacuously true;
            // but we still must assert a property that the correct contract satisfies for ALL inputs.
            // Here we assert that a successful call increments by 1; when call reverted, this assertion
            // is not applicable and we skip by asserting that revert occurred (i.e., ok==false) leads
            // to the same relationship: afterCount == before (no state change).
            assertTrue(afterCount == before);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz two senders and two amounts. The property: if two successful receive() calls are made
    // (possibly by same or different senders) with nonzero value, then depositsCount increases by 1 for each call
    // (i.e., after both calls it's exactly prior + 2). The mutant will block the second successful increment when
    // the first made depositsCount nonzero, so some fuzzed inputs will make the mutant differ.
    function testFuzz_property(address sender1, address sender2, uint256 v1, uint256 v2) public {
        // admissible domain: nonzero positive values and valid distinct/non-distinct senders are allowed
        vm.assume(v1 > 0 && v2 > 0);
        // fund the fuzzed senders so they can send ETH
        vm.deal(sender1, v1);
        vm.deal(sender2, v2);

        // record starting depositsCount
        uint start = c.depositsCount();

        // first deposit from sender1
        vm.prank(sender1);
        (bool ok1, ) = address(c).call{value: v1}("");
        // require the call succeeded on-chain; both reference and mutant accept the first deposit when start==0
        // but we only assert overall rule at the end
        // second deposit from sender2
        vm.prank(sender2);
        (bool ok2, ) = address(c).call{value: v2}("");

        // We only proceed to check the rule for the case where both low-level calls succeeded (both contracts accepted value)
        // If either call reverted, we skip the assertion by assuming both succeeded as admissible domain — keep domain wide
        vm.assume(ok1 && ok2);

        // After two successful receive() calls with positive value, correct contract always increments depositsCount by 2
        // (i.e., final == start + 2). The mutant blocks increments once depositsCount is nonzero, so some inputs will fail.
        uint finalCount = c.depositsCount();
        assertTrue(finalCount == start + 2);
    }
}

