pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter is the amount of wei sent to receive(); the fuzzer will search for a value
    // that causes wrapping in the buggy mutant. We keep domain wide but non-negative by using uint256.
    function testFuzz_property(uint256 amount) public {
        // keep amount within the accountable range but allow full uint256 to let fuzzer find overflow
        // Use an actor address for sending funds
        address sender = address(0xBEEF);
        // fund the sender so it can send `amount` (if amount > type(uint256).max for balance, vm.deal will cap, but that's fine)
        vm.deal(sender, amount);

        // record before value
        uint256 before = c.depositsCount();

        // perform the payable call as sender to hit receive()
        vm.prank(sender);
        // call receive by sending empty data with value
        (bool ok, ) = address(c).call{value: amount}("");
        // We don't assert on ok here; both reference and mutant accept the call. The distinguishing property
        // is about depositsCount monotonicity.

        uint256 after = c.depositsCount();

        // General rule: depositsCount must not decrease after any receive() invocation
        assertTrue(after >= before);
    }
}

