pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter is an initial depositsCount we try to arrange by directly setting storage via repeated deposits from an address.
    // We do NOT use restricted vm.* cheatcodes except vm.deal and vm.prank to drive payable receive. We keep domain wide.
    function testFuzz_property(uint256 initialDeposits) public {
        // Keep initialDeposits within reasonable bounds so we can loop to set up state; but wide enough to include uint256 max wrap scenario.
        uint256 target = initialDeposits % 1024; // bound to a practical loop size but still fuzzed

        // prepare an actor with funds to make deposits
        address depositor = address(0xBEEF);
        vm.deal(depositor, 1 ether);

        // bring depositsCount to `target` by sending small amounts repeatedly
        for (uint256 i = 0; i < target; i++) {
            vm.prank(depositor);
            // send a trivial value to trigger receive
            (bool ok,) = address(c).call{value: 1 wei}("");
            require(ok);
        }

        uint256 before = c.depositsCount();

        // now perform one more deposit to exercise receive
        vm.prank(depositor);
        (bool ok,) = address(c).call{value: 1 wei}("");
        require(ok);

        uint256 after = c.depositsCount();

        // GENERAL RULE: correct contract always increments by exactly 1 on successful receive
        assertTrue(after == before + 1);
    }
}

