pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the starting depositsCount and the deposit amount
    function testFuzz_property(uint256 startCount, uint256 amount) public {
        // keep startCount within the uint range (it's already), but bind it to a wide domain
        // we want to allow the fuzzer to reach the wrap boundary, so do not constrain tightly
        // set the storage directly by funding the contract and then manipulating its depositsCount
        // We cannot write c.depositsCount directly; instead, simulate by repeatedly calling receive
        // However calling receive repeatedly is expensive; instead we will use vm.record and vm.prank not allowed
        // Simpler: use a helper contract to set depositsCount by performing startCount deposits via a loop up to a reasonable cap
        // But we must keep domain wide; constrain startCount to a practical cap to avoid OOG in tests
        uint256 boundedStart = bound(startCount, 0, 1024);

        // prepare a donor EOA
        address donor = address(0xBEEF);
        vm.deal(donor, 1 ether * 1000);

        // perform boundedStart deposits to set c.depositsCount = boundedStart
        for (uint256 i = 0; i < boundedStart; i++) {
            vm.prank(donor);
            // call receive by sending 1 wei
            (bool sent,) = address(c).call{value: 1}("");
            require(sent);
        }

        // Record before value via the public getter
        uint256 before = c.depositsCount();

        // Prepare the depositor with enough balance
        address depositor = address(0xCAFE);
        vm.deal(depositor, amount + 1);
        vm.prank(depositor);
        // Perform the deposit: call receive with 'amount' wei
        (bool ok,) = address(c).call{value: amount}("");
        // call succeeded or failed — deposit is a receive so it should succeed unless OOG
        // Read after value
        uint256 after = c.depositsCount();

        // The general property: for the reference contract, after == before + 1 for all inputs
        // Use a single assertion that expresses that property
        assertTrue(after == before + 1);
    }
}

