pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the sender and the amount sent. The general rule:
    // Sending any positive ETH to the contract via its receive() should increment depositsCount by 1
    // (and the call should succeed). The mutant that reverts breaks this for some inputs (e.g., any positive amount).
    function testFuzz_property(address sender, uint128 amount) public {
        // Keep amount in a wide, admissible domain but ensure we test positive transfers
        uint128 boundedAmount = uint128(bound(amount, 0, type(uint128).max));

        // We need a positive amount to exercise payable receive. If amount is zero, the receive still can be invoked
        // but reference increments depositsCount when a payable transfer of >0 occurs; keep admissible wide by allowing 0.

        // Record prior count
        uint prior = c.depositsCount();

        bool ok;
        // Fund the sender account in VM so it can send ETH
        vm.deal(sender, boundedAmount);
        vm.prank(sender);
        // Try to send boundedAmount to c via a plain transfer (which triggers receive())
        // Capture whether the call succeeded (ok == true) or reverted (ok == false)
        try c.call{value: boundedAmount}("") {
            // If low-level call path existed on C, this branch wouldn't be used; we instead use address(c).call below
            ok = true;
        } catch {
            ok = false;
        }

        // But above try/catch won't call receive(); use address(c).call to send value and trigger receive
        // Re-do with try/catch around address(c).call to observe success/failure
        bool callOk;
        (callOk, ) = address(c).call{value: boundedAmount}("");

        // After the attempt, read depositsCount
        uint after = c.depositsCount();

        // The universal property we assert: If the transfer succeeded (callOk == true) then depositsCount increased by exactly 1.
        // This holds for the reference for all inputs; the mutant that reverts will make callOk == false and/or prevent the increment
        // for some positive amount/sender, causing this assertion to fail.
        assertTrue(!callOk || after == prior + 1);
    }
}

