    function setUp() public { c = new C(); }

    // fuzzed params: depositAmount is the amount sent into C via receive(),
    // sendValue is the value passed to sendMoney (may be 0..depositAmount)
    function testFuzz_property(uint256 depositAmount, uint256 sendValue) public {
        // keep amounts in reasonable Ether range and avoid overflow in arithmetic within C
        depositAmount = bound(depositAmount, 1, 1e20); // 1 wei .. 100 ETH-ish
        sendValue = bound(sendValue, 0, depositAmount);

        // deploy an adversarial recipient whose fallback consumes all gas and then reverts
        BadRecipient bad = new BadRecipient();

        // fund an external actor so we can send ETH into c via its receive()
        address payer = address(0xBEEF);
        vm.deal(payer, depositAmount);
        vm.prank(payer);
        // send depositAmount to c triggering receive()
        (bool okSend, ) = address(c).call{value: depositAmount}("");
        require(okSend);

        // Now call sendMoney to the adversarial contract with sendValue
        // must be performed by owner; set msg.sender to owner (setUp deployed C so owner == address(this) in setUp)
        // but setUp created c from this test contract, so this contract is owner
        // call sendMoney with bad recipient
        c.sendMoney(address(bad), sendValue, "");

        // After that interaction, the reference C should allow owner to withdraw the full balance
        // We observe this by attempting to call withdrawAll() and catching whether it reverts.
        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // The single assertion: reference (correct) contract always allows withdrawAll() for any admissible inputs
        // (this will hold for the provided reference C but the mutant described will fail for some inputs)
        assertTrue(withdrew);
    }
}

// Adversarial helper: consumes all gas then reverts in fallback()
contract BadRecipient {
    fallback() external payable {
        // burn gas
        for (uint i = 0; i < 1000; i++) {
            // do some useless work to consume gas
            uint x = i * i;
            x;
        }
        revert("bad");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // caller is any address (msg.sender of this function). We supply: depositAmount to send to c,
    // withdrawAmount that caller will try to withdraw. ownerAddr is the known owner of c (public getter).
    // The test: if msg.sender is NOT the owner, then calling c.withdraw(withdrawAmount) must NOT reduce address(c).balance.
    // On P this holds because withdraw is onlyOwner; on M it fails because withdraw is public.
    function runTest(uint depositAmount, uint withdrawAmount) public payable {
        // ensure this contract has enough balance to forward depositAmount
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        address owner = c.owner();

        // deposit into c so it has funds; depositsCount's receive increments when receiving
        // send Ether to c using receive() by calling low-level transfer via address(c).call{value:...}()
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        // read balance before attempted withdraw
        uint balBefore = address(c).balance;

        // If the caller of this test is the owner, the behavior is allowed to reduce balance.
        // We only assert the invariant for non-owners. So require the caller is NOT the owner.
        require(msg.sender != owner, "test caller must not be owner");

        // Attempt to withdraw as non-owner
        // This is a state-changing call and must be a top-level statement
        // It may revert under P (due to onlyOwner) or succeed under M.
        c.withdraw(withdrawAmount);

        uint balAfter = address(c).balance;

        // Assert: if caller is non-owner then balance must not decrease (P holds, M violates)
        assert(balAfter >= balBefore);
    }

    // allow contract to be funded for the test
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // drive: deposit funds then attempt withdraw by owner (this contract must be owner in P case)
    function runTest(uint depositAmount, uint withdrawAmount) public {
        // preconditions for meaningful test
        require(depositAmount > 0);
        require(withdrawAmount <= depositAmount);

        // ensure this test contract is the owner in the original contract P
        // (C sets owner = msg.sender at its construction). We rely on the external test harness
        // to have deployed/initialized C with this contract as owner.

        // send Ether to c to trigger receive() and increment depositsCount
        require(address(this).balance >= depositAmount);
        // deposit into c
        (bool sent,) = address(c).call{value: depositAmount}(new bytes(0));
        require(sent);

        // record contract balance before withdraw
        uint balBefore = address(c).balance;

        // attempt withdraw as owner (this contract). On P this should succeed; on M it will revert.
        c.withdraw(withdrawAmount);

        // observe balance after withdraw
        uint balAfter = address(c).balance;

        // assert that balance decreased by exactly withdrawAmount
        assert(balBefore - balAfter == withdrawAmount);
    }

    // allow this contract to receive Ether so it can fund c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition needed: we express property about whether withdraw reverts when called by msg.sender
        bool reverted; try c.withdraw(0) { reverted = false; } catch { reverted = true; }
        // On the original contract, the deployer of C is the owner, and calling withdraw should not revert.
        // Hence assert that this call did not revert.
        assert(reverted == false);
    }
    receive() external payable { }
}

