    function testFuzz_property(address target, uint256 value) public {
        // keep address non-zero to be a plausible contract deploy target; fuzzer can still pick zero but that's admissible
        // limit value to reasonable max so vm.deal works in test environment
        value = bound(value, 0, 1 ether);

        // Deploy a helper that will revert when called to model an adversarial external party
        Reverter rev = new Reverter();
        address callee = target == address(0) ? address(rev) : target;

        // Fund the contract so it has balance to forward and to allow withdraw attempts
        vm.deal(address(this), 2 ether);
        // Make the contract receive some ether via depositsCount increment path: call receive
        // The contract's owner is this test contract because new C() sets owner = msg.sender in setUp()
        // We need to fund c so it can forward value and still have withdraw balance
        vm.prank(address(this));
        // Send some ETH to contract C using its receive() by low-level call
        (bool sent,) = address(c).call{value: 1 ether}("");
        require(sent);

        // Now call sendMoney as the owner (this test contract is the owner) to forward `value` to callee
        // If callee is an EOA, call will succeed; if it's the Reverter, it will revert inside but sendMoney doesn't check return
        vm.prank(address(this));
        // Prepare empty data
        bytes memory data = "";
        // Wrap call in try/catch to observe if sendMoney itself reverts (shouldn't on reference)
        bool ok;
        try c.sendMoney{value: value}(callee, value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule to assert: on the correct contract C, after sendMoney as owner, the owner can still withdraw the remaining balance.
        // We assert that calling withdrawAll as the owner succeeds (does not revert) on the reference implementation for all inputs.
        // To check that, attempt withdrawAll and catch revert; assertTrue over the success flag.
        bool withdrawOk;
        try c.withdrawAll() {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // Single assertion: on the correct contract this must be true for all fuzzed inputs; the mutant will fail for some inputs
        assertTrue(withdrawOk);
    }
}

// adversarial helper that always reverts on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

