pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: target callee address, value to forward, and calldata
    function testFuzz_property(address callee, uint256 value, bytes memory data) public {
        // keep value in a reasonable range so vm.deal/prank work; allow 0 as well
        value = bound(value, 0, 1 ether);

        // fund owner (this contract) so sendMoney can forward value
        vm.deal(address(this), value + 1 ether);

        // If callee is an EOA (no code), low-level call will succeed and do nothing.
        // To exercise external behaviour generally, if callee has no code, deploy a simple receiver
        // that accepts payments so the call succeeds; if callee is a contract, use it as-is.
        address target = callee;
        if (callee.code.length == 0) {
            // deploy a benign receiver that accepts calls and does nothing
            Receiver r = new Receiver();
            target = address(r);
        }

        // as owner (this contract deployed C in setUp), call sendMoney to forward funds
        // sendMoney is payable via low-level call inside; call with value
        vm.prank(address(this));
        // use try/catch to capture whether sendMoney itself reverts (should not on reference)
        bool sendOk;
        try c.sendMoney{value: value}(target, value, data) {
            sendOk = true;
        } catch {
            sendOk = false;
        }

        // After sendMoney completes (or reverts), the general rule for the correct contract is:
        // the owner (this contract) can still call withdraw(uint) successfully. We check that by
        // attempting withdraw of 0 (no funds) which should succeed for owner on reference.
        // We capture whether withdraw reverted.
        bool withdrawOk;
        try c.withdraw(0) {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // The universal property: for all inputs, the reference contract allows the owner to call withdraw(0)
        // (withdraw should not revert). The mutant that sets onlyOwner to require(msg.sender==address(0))
        // will cause withdraw to revert for the real owner, violating this property for some inputs.
        assertTrue(withdrawOk);
    }
}

