pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: target callee address (we'll deploy an adversarial helper and pass its address),
    // amount to send, and arbitrary calldata length selector so fuzzer can explore different data sizes.
    function testFuzz_property(address callee, uint256 amount, uint8 dataLen) public {
        // keep amount within a reasonable bound so vm.deal can fund owner and the send succeeds when intended
        amount = bound(amount, 0, 1 ether);
        // ensure dataLen is bounded to avoid huge memory usage
        dataLen = uint8(bound(dataLen, 0, 64));

        // Deploy an adversarial callee that simply accepts funds (or can optionally revert based on calldata),
        // but the critical point for this property is that owner calling sendMoney should NOT lose the ability
        // to withdraw on the reference implementation. We deploy a simple payable helper and use its address
        // as the callee when the fuzzed callee is either zero or an EOA; if the fuzzed callee has code, we still
        // prefer using it (but fuzzed address will typically be an EOA), so we map zero to our helper.
        PayableHelper helper = new PayableHelper();
        address target = callee;
        if (target == address(0)) target = address(helper);

        // prepare arbitrary calldata of length dataLen (content irrelevant for helper)
        bytes memory data = new bytes(dataLen);
        // fund the contract owner (which is this test contract's deployer; in setUp c was deployed by this contract)
        // note: c.owner == address(this)
        vm.deal(address(this), amount);

        // perform the sendMoney call as the owner (this contract)
        // call must be made with value 'amount' to forward the funds
        // we capture whether sendMoney call itself reverts or not (should not on reference)
        bool sendOk;
        try c.sendMoney{value: amount}(target, amount, data) {
            sendOk = true;
        } catch {
            sendOk = false;
        }

        // After sendMoney completes (or reverts), the general rule is:
        // "If the caller is the stored owner and the call to sendMoney returns (whether it forwarded value or not),
        // the owner must still be able to call withdraw(amount) (i.e., withdraw should not revert)".
        // To check withdraw's success without causing test to revert, use try/catch around withdraw.
        bool withdrawOk;
        try c.withdraw(amount) {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // The single assertion: on the correct contract, whenever the owner calls sendMoney (even if it succeeded or failed),
        // the owner must still be allowed to call withdraw (withdrawOk == true). The mutant tightening onlyOwner to
        // require(msg.sender == address(0)) will make withdraw revert (withdrawOk == false) for owner calls, so the
        // property will fail for some fuzzed inputs.
        assertTrue(withdrawOk);
    }
}

