        require(sent, "funding C failed");

        // craft some calldata for the callee (use the fuzzed selector to vary calldata but not necessary)
        bytes memory data = abi.encodePacked(targetSelector);

        // owner (this) calls sendMoney on c forwarding no extra ETH (sendMoney uses contract balance)
        // since sendMoney is protected by onlyOwner, and this is the owner, call should succeed on reference
        bool ok;
        try c.sendMoney(address(callee), amount, data) {
            ok = true;
        } catch {
            ok = false;
