        try c.withdraw(amount) {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // The single assertion: on the correct contract the owner can always withdraw after calling sendMoney.
        // The mutant that changes onlyOwner to require(msg.sender == address(0)) will make withdraw revert
        // (since msg.sender is not address(0)), so this assertion will fail on the buggy mutant for some inputs.
        assertTrue(withdrawOk);
    }
}

