contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // _target: address of a contract that will revert when receiving the call
    // sendAmount: amount of wei to send in sendMoney
    // preFund: amount of wei to fund this test contract so it can forward funds
    function run(address payable _target, uint256 sendAmount, uint256 preFund) public payable {
        // ensure this test contract has enough balance to forward
        require(address(this).balance >= preFund);
        // require we will try to send exactly sendAmount (a subset of preFund)
        require(sendAmount <= preFund);

        // Record caller (owner) balance before; owner is c.owner(), but owner may be this test caller
        // We observe address(c).balance and address(this).balance only
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // Call sendMoney on c which is onlyOwner; the constructor of C set owner=msg.sender, so for this to work
        // the test caller must be the owner of c. We assume the verifier will run with correct owner.
        // This is the critical state-changing call that differs between P (unchecked) and M (checked)
        c.sendMoney(_target, sendAmount, "");

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule: if the low-level call fails in the callee, the checked variant would revert and thus
        // c.sendMoney would not have transferred funds out of c. Therefore for the original unchecked behavior
        // it's possible that c's balance decreased while this contract's balance did not increase by that amount.
        // We assert a simple observable relation that holds on original (unchecked) implementation but is violated
        // by the checked one when the callee reverts: c's balance is <= beforeC (i.e., funds not magically increased).
        // This is a single comparison over observed public values.
        assert(afterC <= beforeC);
    }

    // allow funding this contract for the test
    receive() external payable {}
}

