        // Ensure this test call sends no ETH to this test contract; funds to forward must come from this contract's balance.
        require(address(this).balance >= value);

        bool reverted;
        try c.sendMoney{value: value}(target, value, data) { reverted = false; } catch { reverted = true; }

        // General rule: when the caller is owner and the contract has at least `value` balance, sendMoney does not revert
